INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Zerlegung in Teilschritte ein wesentlicher Schritt im PSP?', 2, '[{"text": "Ja", "correct": true, "because": "Strukturiert das Projekt"}, {"text": "Nein", "correct": false, "because": "Es ist zentral dafür"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel der Zerlegung in Teilschritte?', 3, '[{"text": "Projekt in handhabbare Abschnitte teilen", "correct": true, "because": "Fördert Übersicht"}, {"text": "Kosten direkt kalkulieren", "correct": false, "because": "Anderer Fokus"}, {"text": "Team motivieren", "correct": false, "because": "Nebenaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Zerlegung führt zu Arbeitspaketen. b) Sie wird nur im Controlling genutzt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Planung entscheidend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ergebnisse entstehen durch die Zerlegung in Teilschritte?', 4, '[{"text": "Teilprojekte", "correct": true, "because": "Zwischenstufen"}, {"text": "Vage Anweisungen", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Arbeitspakete", "correct": true, "because": "Kleine Einheiten"}, {"text": "Hierarchische Ebenen", "correct": true, "because": "Strukturieren PSP"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein PSP ohne Zerlegung in Teilschritte funktionieren?', 2, '[{"text": "Nein", "correct": true, "because": "Zerlegung ist Grundlage"}, {"text": "Ja", "correct": false, "because": "Unstrukturiert unpraktisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Zerlegung ist unzureichend?', 3, '[{"text": "Irgendwas machen", "correct": true, "because": "Zu ungenau"}, {"text": "1.1.3 Server konfigurieren", "correct": false, "because": "Klar und strukturiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Zerlegung in Teilschritte nur für komplexe Projekte nötig?', 2, '[{"text": "Nein", "correct": true, "because": "Auch einfache Projekte brauchen sie"}, {"text": "Ja", "correct": false, "because": "Universelle Relevanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technik unterstützt die Zerlegung?', 3, '[{"text": "Top-Down-Ansatz", "correct": true, "because": "Von grob zu fein"}, {"text": "Keine Struktur", "correct": false, "because": "Fehlt Systematik"}, {"text": "Zufällige Teilung", "correct": false, "because": "Unübersichtlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Zerlegung verbessert die Planbarkeit. b) Sie ist immer endgültig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, anpassbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne Zerlegung in Teilschritte?', 3, '[{"text": "Projekt wird unüberschaubar", "correct": true, "because": "Keine Struktur"}, {"text": "Schnellere Umsetzung", "correct": false, "because": "Eher Verzögerung"}, {"text": "Kostenreduktion", "correct": false, "because": "Ineffizienz möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Zerlegung ohne Anforderungen erfolgen?', 2, '[{"text": "Nein", "correct": true, "because": "Anforderungen geben Richtung"}, {"text": "Ja", "correct": false, "because": "Unklarheit droht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt eine gute Zerlegung?', 3, '[{"text": "2.1.2 Backup einrichten", "correct": true, "because": "Klar und strukturiert"}, {"text": "Irgendwas sichern", "correct": false, "because": "Zu ungenau"}, {"text": "Team soll etwas machen", "correct": false, "because": "Nicht spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Zerlegung nur für den Projektleiter relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Team braucht Übersicht"}, {"text": "Ja", "correct": false, "because": "Projektweite Relevanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale haben Teilschritte?', 4, '[{"text": "Abgrenzbare Aufgaben", "correct": true, "because": "Definieren Umfang"}, {"text": "Unklare Ziele", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Zuweisbar an Personen", "correct": true, "because": "Fördern Verteilung"}, {"text": "Klar beschrieben", "correct": true, "because": "Fördern Verständnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss die Zerlegung dokumentiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Nachweis wichtig"}, {"text": "Nein", "correct": false, "because": "Dokumentation hilft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktion hat die Zerlegung?', 3, '[{"text": "Projekt steuerbar machen", "correct": true, "because": "Fördert Kontrolle"}, {"text": "Zeitplan direkt erstellen", "correct": false, "because": "Späterer Schritt"}, {"text": "Team neu einteilen", "correct": false, "because": "Durchführungsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Zerlegung ohne Hierarchie erfolgen?', 2, '[{"text": "Nein", "correct": true, "because": "Hierarchie ist Kern"}, {"text": "Ja", "correct": false, "because": "Unstrukturiert unpraktisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor erschwert die Zerlegung?', 3, '[{"text": "Unklare Projektziele", "correct": true, "because": "Verhindern Struktur"}, {"text": "Klarer Umfang", "correct": false, "because": "Fördert Zerlegung"}, {"text": "Gute Datenbasis", "correct": false, "because": "Unterstützt Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Zerlegung unterstützt Ressourcenplanung. b) Sie ist nur für technische Projekte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, breit anwendbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Vorteil der Zerlegung?', 3, '[{"text": "Erleichterte Koordination", "correct": true, "because": "Fördert Effizienz"}, {"text": "Maximale Unklarheit", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Struktur", "correct": false, "because": "Fördert Ordnung"}]');
